CREATE TABLE IF NOT EXISTS `music_tracks` (`trackKey` TEXT NOT NULL, `title` TEXT NOT NULL, `artist` TEXT NOT NULL, `album` TEXT NOT NULL, `sourcePackage` TEXT NOT NULL, `playCount` INTEGER NOT NULL, `totalDurationMs` INTEGER NOT NULL, `firstPlayedAt` INTEGER NOT NULL, `lastPlayedAt` INTEGER NOT NULL, `userNotes` TEXT NOT NULL, `isFavorite` INTEGER NOT NULL, `syncedLyrics` TEXT, `plainLyrics` TEXT, `albumArtUri` TEXT, PRIMARY KEY(`trackKey`))
CREATE INDEX IF NOT EXISTS `index_music_tracks_isFavorite` ON `music_tracks` (`isFavorite`)
CREATE INDEX IF NOT EXISTS `index_music_tracks_playCount` ON `music_tracks` (`playCount`)
CREATE INDEX IF NOT EXISTS `index_music_tracks_lastPlayedAt` ON `music_tracks` (`lastPlayedAt`)
CREATE TABLE IF NOT EXISTS `music_listening_sessions` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `trackKey` TEXT NOT NULL, `sourcePackage` TEXT NOT NULL, `startTimeMs` INTEGER NOT NULL, `endTimeMs` INTEGER NOT NULL, `durationMs` INTEGER NOT NULL, `isCompleted` INTEGER NOT NULL)
CREATE INDEX IF NOT EXISTS `index_music_listening_sessions_trackKey` ON `music_listening_sessions` (`trackKey`)
CREATE INDEX IF NOT EXISTS `index_music_listening_sessions_startTimeMs` ON `music_listening_sessions` (`startTimeMs`)
CREATE TABLE IF NOT EXISTS `lyrics_cache` (`trackKey` TEXT NOT NULL, `plainLyrics` TEXT, `syncedLyricsLrc` TEXT, `chordsAmDm` TEXT, `userNotes` TEXT, `provider` TEXT NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`trackKey`))
CREATE TABLE IF NOT EXISTS `achievements` (`id` TEXT NOT NULL, `title` TEXT NOT NULL, `description` TEXT NOT NULL, `iconRes` TEXT NOT NULL, `isUnlocked` INTEGER NOT NULL, `unlockedAt` INTEGER, `currentProgress` INTEGER NOT NULL, `maxProgress` INTEGER NOT NULL, `tier` TEXT NOT NULL, `category` TEXT NOT NULL, PRIMARY KEY(`id`))
CREATE TABLE IF NOT EXISTS `lyrics_rejections` (`trackKey` TEXT NOT NULL, `sourceId` TEXT NOT NULL, `rejectedAt` INTEGER NOT NULL, PRIMARY KEY(`trackKey`, `sourceId`))
CREATE INDEX IF NOT EXISTS `index_lyrics_rejections_trackKey` ON `lyrics_rejections` (`trackKey`)
CREATE INDEX IF NOT EXISTS `index_lyrics_rejections_sourceId` ON `lyrics_rejections` (`sourceId`)
CREATE TABLE IF NOT EXISTS `custom_lyrics_rules` (`id` TEXT NOT NULL, `domain` TEXT NOT NULL, `name` TEXT NOT NULL, `ruleJson` TEXT NOT NULL, `isEnabled` INTEGER NOT NULL, `priority` INTEGER NOT NULL, `isBuiltIn` INTEGER NOT NULL, `author` TEXT NOT NULL, `version` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`id`))
CREATE INDEX IF NOT EXISTS `index_custom_lyrics_rules_domain` ON `custom_lyrics_rules` (`domain`)
CREATE INDEX IF NOT EXISTS `index_custom_lyrics_rules_isEnabled` ON `custom_lyrics_rules` (`isEnabled`)
CREATE INDEX IF NOT EXISTS `index_custom_lyrics_rules_priority` ON `custom_lyrics_rules` (`priority`)
CREATE TABLE IF NOT EXISTS `blacklist_rules` (`id` TEXT NOT NULL, `ruleType` TEXT NOT NULL, `pattern` TEXT NOT NULL, `matchMode` TEXT NOT NULL, `isEnabled` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, PRIMARY KEY(`id`))
CREATE INDEX IF NOT EXISTS `index_blacklist_rules_isEnabled` ON `blacklist_rules` (`isEnabled`)
CREATE INDEX IF NOT EXISTS `index_blacklist_rules_ruleType` ON `blacklist_rules` (`ruleType`)
CREATE TABLE IF NOT EXISTS room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT)
